**`src/capitalize.ts`**
```ts
/**
 * Uppercases the first character of a string.
 * @example capitalize("hello") // "Hello"
 */
export function capitalize(input: string): string {
  if (input.length === 0) return input;
  return input.charAt(0).toUpperCase() + input.slice(1);
}
```

**`src/truncate.ts`**
```ts
/**
 * Shortens a string to `maxLength` characters, appending a suffix if truncated.
 * The suffix counts toward `maxLength`.
 * @example truncate("Hello world", 8) // "Hello..."
 */
export function truncate(input: string, maxLength: number, suffix = "..."): string {
  if (maxLength < 0) {
    throw new RangeError("maxLength must be non-negative");
  }
  if (input.length <= maxLength) return input;
  if (maxLength <= suffix.length) return suffix.slice(0, maxLength);
  return input.slice(0, maxLength - suffix.length) + suffix;
}
```

**`tests/capitalize.test.ts`**
```ts
import { describe, it, expect } from "vitest";
import { capitalize } from "../src/capitalize";

describe("capitalize", () => {
  it("uppercases the first letter", () => {
    expect(capitalize("hello")).toBe("Hello");
  });

  it("leaves the rest of the string unchanged", () => {
    expect(capitalize("hELLO")).toBe("HELLO");
  });

  it("returns an empty string unchanged", () => {
    expect(capitalize("")).toBe("");
  });

  it("handles single characters", () => {
    expect(capitalize("a")).toBe("A");
  });

  it("does not alter strings starting with non-letters", () => {
    expect(capitalize("1abc")).toBe("1abc");
  });
});
```

**`tests/truncate.test.ts`**
```ts
import { describe, it, expect } from "vitest";
import { truncate } from "../src/truncate";

describe("truncate", () => {
  it("returns the string unchanged if within the limit", () => {
    expect(truncate("Hello", 10)).toBe("Hello");
  });

  it("returns the string unchanged if exactly at the limit", () => {
    expect(truncate("Hello", 5)).toBe("Hello");
  });

  it("truncates and appends the default suffix", () => {
    expect(truncate("Hello world", 8)).toBe("Hello...");
  });

  it("supports a custom suffix", () => {
    expect(truncate("Hello world", 6, "…")).toBe("Hello…");
  });

  it("handles maxLength smaller than the suffix", () => {
    expect(truncate("Hello world", 2)).toBe("..");
  });

  it("throws on negative maxLength", () => {
    expect(() => truncate("Hello", -1)).toThrow(RangeError);
  });
});
```

