import { load, save } from '../lib/store.js';

export const name = 'add';
export const description = 'Increment a tally';

export async function handler([key, amount = '1']) {
  const data = await load();
  data[key] = (data[key] ?? 0) + Number(amount);
  await save(data);
  return `${key}: ${data[key]}`;
}
```

