const store = require('../lib/store');

async function add(name, amount = 1) {
  const data = await store.load();
  data[name] = (data[name] || 0) + Number(amount);
  await store.save(data);
  return data[name];
}

function register(program) {
  program
    .command('add <name> [amount]')
    .description('Increment a tally')
    .action(async (name, amount) => {
      const total = await add(name, amount);
      console.log(`${name}: ${total}`);
    });
}

module.exports = register;
module.exports.add = add; // exported for unit testing
