**`src/commands/add.js`**
```js
import { load, save } from '../lib/store.js';

export default {
  name: 'add',
  description: 'Increment a tally',
  usage: 'tally add <name> [amount]',
  async run([name, amount = '1'], { storePath } = {}) {
    if (!name) throw new Error('Missing <name>');
    const data = await load(storePath);
    data[name] = (data[name] ?? 0) + Number(amount);
    await save(data, storePath);
    return `${name}: ${data[name]}`;
  },
};
```

**`test/commands/add.test.js`** (using Node's built-in test runner)
```js
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import add from '../../src/commands/add.js';

test('add increments a new tally to 1', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'tally-'));
  const storePath = join(dir, 'store.json');
  const out = await add.run(['coffee'], { storePath });
  assert.equal(out, 'coffee: 1');
});

test('add throws without a name', async () => {
  await assert.rejects(() => add.run([]), /Missing <name>/);
});
```

