/**
 * Shortens a string to at most `maxLength` characters,
 * appending `ellipsis` if truncation occurred.
 */
export function truncate(
  input: string,
  maxLength: number,
  ellipsis = "..."
): string {
  if (input.length <= maxLength) return input;
  if (maxLength <= ellipsis.length) return ellipsis.slice(0, Math.max(0, maxLength));
  return input.slice(0, maxLength - ellipsis.length) + ellipsis;
}
```

