**`src/commands/add.js`**
```js
export const name = 'add';
export const description = 'Add to a named counter';

export async function handler({ args, storage, out }) {
  const [counterName, amount = '1'] = args;
  const n = Number(amount);
  if (!counterName || Number.isNaN(n)) {
    throw new Error('Usage: tally add <name> [amount]');
  }
  const data = await storage.read();
  data[counterName] = (data[counterName] ?? 0) + n;
  await storage.write(data);
  out(`${counterName}: ${data[counterName]}`);
}
```

Each command exports `name`, `description`, and a `handler` that receives its dependencies (`storage`, `out`). This makes commands easy to unit test without touching the filesystem or stdout.

