const storage = require('../lib/storage');

function add(name, amount = 1, { store = storage } = {}) {
  const data = store.read();
  data[name] = (data[name] || 0) + Number(amount);
  store.write(data);
  return data[name];
}

module.exports = (program) => {
  program
    .command('add <name> [amount]')
    .description('Increment a counter')
    .action((name, amount) => {
