const storage = require('../lib/storage');

module.exports = {
  name: 'add',
  description: 'Add an item to the tally',
  args: ['<item>'],
  options: [
    { flags: '-n, --count <number>', description: 'Amount to add', default: 1 },
  ],
  async action(item, opts) {
    const data = await storage.load();
    data[item] = (data[item] || 0) + Number(opts.count);
    await storage.save(data);
    return `${item}: ${data[item]}`;
  },
};
```

