const { Command } = require('commander');
const commands = require('./commands');
const pkg = require('../package.json');

function run(argv) {
  const program = new Command('tally').version(pkg.version);

  for (const cmd of commands) {
    const c = program.command(`${cmd.name} ${(cmd.args || []).join(' ')}`.trim())
      .description(cmd.description);
    (cmd.options || []).forEach(o => c.option(o.flags, o.description, o.default));
    c.action(async (...args) => {
      const opts = c.opts();
      console.log(await cmd.action(...args.slice(0, -2), opts));
    });
  }

  program.parse(argv);
}

module.exports = { run };
```

