import { load, save } from '../lib/storage.js';

export async function addAction(name, amount = 1, { storage } = {}) {
  const data = await load(storage);
  data[name] = (data[name] ?? 0) + Number(amount);
  await save(data, storage);
  return data[name];
}

export default function register(program) {
