**`src/commands/add.js`** (each command exports its logic separately from its registration so it can be unit tested without the CLI)
```js
import { load, save } from '../lib/storage.js';

export function addCounter(data, name, amount = 1) {
  return { ...data, [name]: (data[name] ?? 0) + amount };
}

export function register(program) {
  program
    .command('add <name> [amount]')
    .description('Increment a counter')
    .action(async (name, amount) => {
      const data = await load();
      const updated = addCounter(data, name, Number(amount ?? 1));
      await save(updated);
      console.log(`${name}: ${updated[name]}`);
    });
}
```

