**`bin/tally.js`**
```js
#!/usr/bin/env node
require('../src/cli').run(process.argv);
```

**`src/cli.js`**
```js
const { Command } = require('commander');
const commands = require('./commands');
const pkg = require('../package.json');

function run(argv) {
  const program = new Command();
  program.name('tally').version(pkg.version);

  for (const register of Object.values(commands)) {
    register(program);
  }

  program.parse(argv);
}

module.exports = { run };
```

**`src/commands/add.js`**
```js
const storage = require('../lib/storage');

function action(item, options, deps = { storage }) {
  const count = Number(options.count ?? 1);
  const data = deps.storage.load();
  data[item] = (data[item] || 0) + count;
  deps.storage.save(data);
  return `${item}: ${data[item]}`;
}

function register(program) {
  program
    .command('add <item>')
    .option('-c, --count <n>', 'amount to add', '1')
    .action((item, options) => console.log(action(item, options)));
}

module.exports = register;
module.exports.action = action;
```

**`test/commands/add.test.js`**
```js
const { test } = require('node:test');
const assert = require('node:assert');
const { action } = require('../../src/commands/add');
const mockStorage = require('../helpers/mock-storage');

test('add increments a new item', () => {
  const storage = mockStorage({});
  const result = action('apples', {}, { storage });
  assert.strictEqual(result, 'apples: 1');
});

test('add respects --count', () => {
  const storage = mockStorage({ apples: 2 });
  const result = action('apples', { count: '3' }, { storage });
  assert.strictEqual(result, 'apples: 5');
});
```

## Design notes

- **Separation of concerns:** Each command exports a `register` function (wires up the parser) and an `action` function (pure logic), so the logic can be unit tested without spawning a process.
- **Dependency injection:** Passing `storage` as a parameter lets tests use an in-memory mock instead of touching the filesystem.
- **Mirrored test tree:** `test/` mirrors `src/`, making tests easy to find.
- **Thin entry point:** `bin/tally.js` only calls into `src/`, so the CLI is importable and testable.
- **Test runner:** This uses Node's built-in `node:test`, so there are no extra dev dependencies. Swap in Jest or Vitest if you prefer, and rename test files or adjust the `test` script accordingly.

To run it locally, use `npm link` in the project root, then call `tally add apples`.

