```js
const { Command } = require('commander');
const commands = require('./commands');
const pkg = require('../package.json');

function buildProgram() {
  const program = new Command();
  program.name('tally').version(pkg.version);
  commands.forEach((register) => register(program));
  return program;
}

function run(argv) {
  buildProgram().parse(argv);
}

module.exports = { buildProgram, run };
```

**`src/commands/index.js`**
```js
module.exports = [
  require('./add'),
  require('./count'),
  require('./reset'),
  require('./report'),
];
```

**`src/commands/add.js`**
```js
const { increment } = require('../lib/counter');

module.exports = function register(program) {
  program
    .command('add <item>')
    .description('Add one to the tally for an item')
    .option('-n, --amount <number>', 'amount to add', '1')
    .action((item, opts) => {
      const total = increment(item, Number(opts.amount));
      console.log(`${item}: ${total}`);
    });
};
```

**`test/lib/counter.test.js`** (using Node's built-in test runner)
```js
