export interface TruncateOptions {
  /** Max length of the returned string. */
  limit?: number;
  /** Suffix appended when the string is shortened. */
  suffix?: string;
}

export function truncate(input: string, options: TruncateOptions = {}): string {
  const { limit = 50, suffix = '…' } = options;
  if (limit <= 0) return '';
  if (input.length <= limit) return input;
  return input.slice(0, Math.max(0, limit - suffix.length)) + suffix;
}
