export interface TruncateOptions {
  /** Maximum length of the result, including the ellipsis. */
  maxLength?: number;
  /** Appended when the input is shortened. */
  ellipsis?: string;
}

/**
 * Shortens `value` to at most `maxLength` characters, appending an ellipsis
 * if anything was cut. Returns the input unchanged when it already fits.
 */
export function truncate(value: string, options: TruncateOptions = {}): string {
