## `src/truncate.ts`

```ts
export interface TruncateOptions {
  /** Maximum length of the returned string, ellipsis included. Default: 80. */
  length?: number;
  /** Appended when the string is shortened. Default: '…'. */
  ellipsis?: string;
}

/**
 * Shortens `value` to at most `options.length` characters, appending an
 * ellipsis when truncation occurs.
 *
 * @example truncate('hello world', { length: 8 }) // 'hello w…'
 */
export function truncate(value: string, options: TruncateOptions = {}): string {
  const { length = 80, ellipsis = '…' } = options;

  if (length <= 0) return '';
  if (value.length <= length) return value;
  if (ellipsis.length >= length) return ellipsis.slice(0, length);

  return value.slice(0, length - ellipsis.length) + ellipsis;
}
```

