## `src/truncate.ts`

```ts
export interface TruncateOptions {
  /** String appended when the input is shortened. Default: '…' */
  ellipsis?: string;
  /** Keep the tail of the string instead of the head. Default: false */
  fromEnd?: boolean;
}

/**
 * Shortens `input` to at most `maxLength` characters, including the ellipsis.
 */
export function truncate(
  input: string,
  maxLength: number,
  options: TruncateOptions = {},
): string {
  const { ellipsis = '…', fromEnd = false } = options;

  if (maxLength <= 0) return '';
  if (input.length <= maxLength) return input;
  if (maxLength <= ellipsis.length) return ellipsis.slice(0, maxLength);

  const keep = maxLength - ellipsis.length;
  const body = fromEnd ? input.slice(-keep) : input.slice(0, keep);
  return fromEnd ? ellipsis + body : body + ellipsis;
}
```

