## `src/truncate.ts`

```ts
export interface TruncateOptions {
  /** Maximum length of the returned string, including the ellipsis. */
  maxLength?: number;
  /** Marker appended when the input is shortened. */
  ellipsis?: string;
}

/**
 * Shortens `input` to at most `maxLength` characters, appending `ellipsis`
 * if anything was cut.
 *
 * @example truncate("hello world", 8) // => "hello w…"
 */
export function truncate(input: string, options: TruncateOptions = {}): string {
  const { maxLength = 50, ellipsis = "…" } = options;

  if (maxLength <= 0) return "";
  if (input.length <= maxLength) return input;

  const keep = Math.max(0, maxLength - ellipsis.length);
  return input.slice(0, keep).trimEnd() + ellipsis;
}
```

