```ts
/**
 * Shortens `input` to at most `maxLength` characters, appending `ellipsis`
 * when the string was cut. The result never exceeds `maxLength`.
 */
export function truncate(
  input: string,
  maxLength: number,
  ellipsis = "…",
): string {
  if (maxLength <= 0) return "";
  if (input.length <= maxLength) return input;
  if (ellipsis.length >= maxLength) return ellipsis.slice(0, maxLength);
  return input.slice(0, maxLength - ellipsis.length) + ellipsis;
}
