### `src/truncate.ts`

```ts
export interface TruncateOptions {
  /** Maximum length of the returned string, including the suffix. */
  length?: number;
  /** Appended when the input is shortened. Defaults to an ellipsis. */
  suffix?: string;
}

/**
 * Shortens `input` to at most `length` characters, appending `suffix`
 * if truncation occurred.
 *
 * @example truncate('a'.repeat(10), { length: 5 }) // 'aaaa…'
 */
export function truncate(input: string, options: TruncateOptions = {}): string {
  const { length = 50, suffix = '…' } = options;

  if (length <= 0) return '';
  if (input.length <= length) return input;

  const keep = Math.max(0, length - suffix.length);
  return input.slice(0, keep).trimEnd() + suffix;
}
```

