```ts
/** Uppercases the first character; the rest of the string is left unchanged. */
export function capitalize(input: string): string {
  if (input.length === 0) return input;
  return input[0].toUpperCase() + input.slice(1);
}
```

**`src/truncate.ts`**
```ts
export interface TruncateOptions {
  /** Maximum length of the returned string, including the suffix. */
  maxLength?: number;
  /** Appended when the input is shortened. */
  suffix?: string;
}

/** Shortens `input` to `maxLength`, appending `suffix` if it was cut. */
export function truncate(input: string, options: TruncateOptions = {}): string {
  const { maxLength = 50, suffix = "…" } = options;

  if (maxLength <= 0) return "";
  if (input.length <= maxLength) return input;

  const keep = Math.max(0, maxLength - suffix.length);
  return input.slice(0, keep) + suffix;
}
```

