import { commands } from './commands/index.js';
import { CliError } from './lib/errors.js';

export async function run(argv, { store, stdout = console.log } = {}) {
  const [name, ...rest] = argv;

  if (!name || name === '--help' || name === '-h') return printHelp(stdout);
  if (name === '--version' || name === '-v') return stdout('1.0.0');

  const cmd = commands[name];
  if (!cmd) throw new CliError(`unknown command: ${name}`, 2);

  return cmd.run(rest, { store, stdout });
}
```

