**`src/commands/add.js`** — the command contract every file in `commands/` follows.

```js
export default {
  name: 'add',
  description: 'Add an amount to a tally',
  usage: 'tally add <label> [amount]',
  options: { amount: { type: 'number', default: 1 } },

  async run(argv, { store, stdout }) {
    const [label, rawAmount] = argv;
    if (!label) throw new CliError('missing <label>', 2);

    const amount = Number(rawAmount ?? 1);
    if (Number.isNaN(amount)) throw new CliError(`invalid amount: ${rawAmount}`, 2);

    const data = await store.read();
    data[label] = (data[label] ?? 0) + amount;
    await store.write(data);

    stdout(`${label}: ${data[label]}`);
  },
};
```

**`src/lib/store.js`** — persistence, isolated so it can be unit-tested with a temp dir.

```js
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';

export function createStore(file) {
  return {
    async read() {
      try {
        return JSON.parse(await readFile(file, 'utf8'));
      } catch (err) {
        if (err.code === 'ENOENT') return {};
        throw err;
      }
    },
    async write(data) {
      await mkdir(dirname(file), { recursive: true });
      const tmp = join(dirname(file), `.${Date.now()}.tmp`);
      await writeFile(tmp, JSON.stringify(data, null, 2));
      await rename(tmp, file); // atomic on POSIX
    },
  };
}
```

