import add from '../../../src/commands/add.js';
import { createStore } from '../../../src/lib/store.js';

describe('commands/add', () => {
  let dir, store, out;

  beforeEach(async () => {
    dir = await mkdtemp(join(tmpdir(), 'tally-'));
    store = createStore(join(dir, 'data.json'));
    out = [];
  });

  afterEach(() => rm(dir, { recursive: true, force: true }));

  test('adds 1 by default', async () => {
    await add.run(['coffee'], { store, stdout: (l) => out.push(l) });
    assert.deepEqual(await store.read(), { coffee: 1 });
    assert.deepEqual(out, ['coffee: 1']);
  });

  test('accumulates repeated labels', async () => {
    await add.run(['coffee', '2'], { store, stdout: () => {} });
    await add.run(['coffee', '3'], { store, stdout: () => {} });
    assert.deepEqual(await store.read(), { coffee: 5 });
  });

  test('rejects a missing label', async () => {
    await assert.rejects(() => add.run([], { store }), /missing <label>/);
  });
});
