export function createContext(initial = { items: {} }) {
  const output = [];
  return {
    output,
    store: {
      data: structuredClone(initial),
      async load() { return this.data; },
      async save(next) { this.data = next; },
    },
    log: (msg) => output.push(msg),
  };
