export const name = 'add';
export const description = 'Add an amount to a tally';
export const usage = 'tally add <label> [amount]';

export async function run({ args, store }) {
  const [label, amount = '1'] = args;
  if (!label) throw new Error('missing <label>');
  const value = Number(amount);
  if (!Number.isFinite(value)) throw new Error(`invalid amount: ${amount}`);

  const data = await store.load();
  data.tallies[label] = (data.tallies[label] ?? 0) + value;
  await store.save(data);
  return `${label}: ${data.tallies[label]}`;
}
```

