import { Command } from 'commander';
import { readPackage } from './util/pkg.js';
import { commands } from './commands/index.js';

export async function run(argv, { stdout = process.stdout } = {}) {
  const program = new Command();
  program
    .name('tally')
    .description('Track and total your entries')
    .version(readPackage().version)
    .exitOverride();               // throw instead of process.exit — testable
    .configureOutput({ writeOut: (s) => stdout.write(s) });

  for (const cmd of commands) program.addCommand(cmd);

  return program.parseAsync(argv, { from: 'user' });
}
