```js
import { Command } from 'commander';
import { parseAmount } from '../core/entries.js';
import { CliError } from '../util/errors.js';

export function makeAddCommand({ store, logger = console }) {
  return new Command('add')
    .description('Add an entry')
    .argument('<amount>', 'numeric value')
    .option('-t, --tag <tag>', 'attach a tag')
    .option('--note <note>', 'optional note')
    .action(async (amount, opts) => {
      const value = parseAmount(amount);                 // throws CliError on bad input
      await store.append({ amount: value, ...opts });
      logger.log(`Added ${value}`);
    });
}

export const add = makeAddCommand({ store: defaultStore });  // default wiring
