export function total(entries) {
  return entries.reduce((sum, e) => sum + e.amount, 0);
}

export function byTag(entries) {
  const out = new Map();
  for (const e of entries) out.set(e.tag ?? 'untagged', (out.get(e.tag ?? 'untagged') ?? 0) + e.amount);
  return Object.fromEntries(out);
}
```

