**`src/commands/add.js`** — uniform shape so the registry can auto-wire anything.
```js
export default {
  name: 'add',
  description: 'Add or increment a tally entry',
  usage: 'tally add <label> [--count <n>]',
  options: {
    count: { type: 'number', default: 1, short: 'c' },
  },
  async run({ args, flags, store, out }) {
    const label = args[0];
    if (!label) throw new UsageError('missing <label>');
    const entries = await store.read();
    const next = addEntry(entries, label, flags.count);
    await store.write(next);
    out(`added ${label} (${flags.count})`);
    return 0;
  },
};
```

