```

**`bin/tally.js`** — keep this thin; everything testable lives in `src/`.

```js
#!/usr/bin/env node
import { run } from '../src/cli.js';

run(process.argv.slice(2))
  .then((code) => { process.exitCode = code; })
  .catch((err) => {
    console.error(err.message);
    process.exitCode = err.exitCode ?? 1;
  });
```

**`src/commands/add.js`** — every command exports the same shape, so the dispatcher stays generic.

```js
export const name = 'add';
export const description = 'Add an item to the tally';
export const usage = 'tally add <label> [--count <n>]';

export async function run(argv, { store }) {
  const [label] = argv;
  if (!label) throw new Error(`Missing <label>. Usage: ${usage}`);

  const count = Number(argv[argv.indexOf('--count') + 1] ?? 1);
  const entry = await store.add({ label, count });

  console.log(`Added ${entry.count} × ${entry.label} (id ${entry.id})`);
  return 0;
}
```

**`src/commands/index.js`** — the registry that makes `commands/` extensible.

```js
import * as add from './add.js';
import * as list from './list.js';
import * as remove from './remove.js';
import * as clear from './clear.js';
import * as exportCmd from './export.js';

export const commands = Object.fromEntries(
  [add, list, remove, clear, exportCmd].map((c) => [c.name, c])
);
```

**`src/cli.js`** — dispatch, help text, exit codes.

```js
import { commands } from './commands/index.js';
import { createStore } from './lib/store.js';

export async function run(argv) {
  const [cmdName, ...rest] = argv;

  if (!cmdName || cmdName === '--help' || cmdName === '-h') {
    printHelp();
    return 0;
  }

  const cmd = commands[cmdName];
  if (!cmd) {
    console.error(`Unknown command: ${cmdName}`);
    printHelp();
    return 1;
  }

  const store = await createStore();
  return cmd.run(rest, { store });
}
```

**`test/unit/commands/add.test.js`** — using Node's built-in runner (zero dependencies).

```js
import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../../../src/commands/add.js';
import { withTempStore } from '../../helpers/tmp-store.js';

let ctx;

beforeEach(async () => { ctx = await withTempStore(); });
afterEach(async () => { await ctx.cleanup(); });

test('adds an item with a default count of 1', async () => {
  await run(['apples'], ctx);

  const entries = await ctx.store.all();
  assert.equal(entries.length, 1);
  assert.equal(entries[0].label, 'apples');
  assert.equal(entries[0].count, 1);
});

test('throws when no label is given', async () => {
  await assert.rejects(() => run([], ctx), /Missing <label>/);
});
```

**`test/helpers/tmp-store.js`** — isolates tests from the user's real data file.

```js
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createStore } from '../../src/lib/store.js';

export async function withTempStore() {
  const dir = await mkdtemp(join(tmpdir(), 'tally-'));
  const store = await createStore({ dataFile: join(dir, 'data.json') });
  return { store, cleanup: () => rm(dir, { recursive: true, force: true }) };
}
```

## Conventions worth keeping

- **One file per command**, each exporting `name`, `description`, `usage`, and `run(argv, ctx)`. Adding a subcommand = one new file + one import in `commands/index.js`.
- **Commands never touch the filesystem directly** — they receive a `store` in `ctx`, so unit tests can inject a temp-backed store and assert on state instead of parsing stdout.
- **Separate `src/` from `test/`**, and keep `unit/` (in-process, fast) distinct from `integration/` (spawns the binary, slower).
- **`bin/` holds only the shim**; all logic lives in `src/` so it can be imported and tested.
- **`.gitignore`**: `node_modules/`, `coverage/`, `*.log`, and a local `tally-data.json`.
- Run locally with `npm link` (or `npm run tally -- list`) so the `bin` entry resolves.
